import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"字幕系统","description":"","frontmatter":{},"headers":[],"relativePath":"features/subtitles.md","filePath":"features/subtitles.md","lastUpdated":1787920745000}'),d={name:"features/subtitles.md"};function n(s,t,i,l,h,b){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="字幕系统" tabindex="-1">字幕系统 <a class="header-anchor" href="#字幕系统" aria-label="Permalink to &quot;字幕系统&quot;">​</a></h1><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>字幕让你的观影体验更完整。ZViewer 提供原生字幕系统，<strong>不再转换为 WebVTT</strong>，而是直接解析各字幕格式并用 HTML/CSS 渲染，样式还原度更高。</p><p>支持<strong>外挂字幕</strong>与<strong>内封字幕</strong>两大类，并且房主选择的字幕会自动同步给房间内所有观众。</p><h2 id="支持的字幕格式" tabindex="-1">支持的字幕格式 <a class="header-anchor" href="#支持的字幕格式" aria-label="Permalink to &quot;支持的字幕格式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格式</th><th>说明</th></tr></thead><tbody><tr><td>SRT</td><td>最常见的文本字幕</td></tr><tr><td>ASS / SSA</td><td>支持定位、颜色、字体等高级样式，渲染时保留</td></tr><tr><td>VTT</td><td>WebVTT 字幕</td></tr><tr><td>SMI</td><td>SAMI 字幕</td></tr><tr><td>SUB</td><td>MicroDVD 字幕</td></tr></tbody></table><h2 id="外挂字幕" tabindex="-1">外挂字幕 <a class="header-anchor" href="#外挂字幕" aria-label="Permalink to &quot;外挂字幕&quot;">​</a></h2><p>外挂字幕是以独立文件形式存在的字幕（如 <code>movie.srt</code>、<code>movie.ass</code>），有以下几种加载方式。</p><h3 id="自动识别" tabindex="-1">自动识别 <a class="header-anchor" href="#自动识别" aria-label="Permalink to &quot;自动识别&quot;">​</a></h3><p>播放 WebDAV / FTP / OpenList / 服务器文件源的影片时，ZViewer 会<strong>自动搜索影片同目录下的同名/同前缀字幕文件</strong>并加载，打开字幕设置即可看到。</p><h3 id="目录浏览" tabindex="-1">目录浏览 <a class="header-anchor" href="#目录浏览" aria-label="Permalink to &quot;目录浏览&quot;">​</a></h3><p>在字幕设置里点 <strong>「浏览目录」</strong>，浏览影片所在目录，选择要加载的字幕文件。</p><h3 id="url-文件上传" tabindex="-1">URL / 文件上传 <a class="header-anchor" href="#url-文件上传" aria-label="Permalink to &quot;URL / 文件上传&quot;">​</a></h3><p>在字幕设置里直接粘贴字幕文件链接，或上传本地字幕文件。</p><h2 id="内封字幕" tabindex="-1">内封字幕 <a class="header-anchor" href="#内封字幕" aria-label="Permalink to &quot;内封字幕&quot;">​</a></h2><p>内封字幕（内嵌字幕）是<strong>封装在视频容器里的字幕轨道</strong>，ZViewer 可以在<strong>浏览器端</strong>直接解析视频容器（MKV）并提取文本字幕轨，<strong>无需服务器安装 FFmpeg</strong>。</p><p>打开「内嵌字幕轨道」按钮即可看到视频容器内的文本字幕轨道列表，选择一条即提取并播放。提取由浏览器完成（自研 MKV demux + 稀疏扫描），<strong>跳过音视频负载</strong>只读字幕字节，GB 级大文件也能快速列出轨道并秒级出字幕。</p><blockquote><p>仅文本字幕轨（SRT / ASS / SSA / WebVTT）可在浏览器提取；位图字幕轨（PGS / VOBSUB）无法提取。</p></blockquote><p>各视频源对内封字幕的支持情况：</p><table tabindex="0"><thead><tr><th>视频源</th><th>内封字幕可用性</th></tr></thead><tbody><tr><td>服务器文件（Server-Files）</td><td>✅ 浏览器直接提取（MKV demux）</td></tr><tr><td>WebDAV / OpenList</td><td>✅ 中转与直链均可（浏览器直接读取源字节）</td></tr><tr><td>Emby / Jellyfin</td><td>✅ 直接调用其自带字幕接口</td></tr><tr><td>MP4 直链 / Bilibili</td><td>❌ 不支持（非 MKV 容器）</td></tr></tbody></table><h3 id="使用步骤" tabindex="-1">使用步骤 <a class="header-anchor" href="#使用步骤" aria-label="Permalink to &quot;使用步骤&quot;">​</a></h3><ol><li>打开播放器 <strong>设置</strong>，切换到 <strong>字幕</strong> 页。</li><li>点击 <strong>「内嵌字幕轨道」</strong>，等待视频容器内的文本字幕轨道列出。</li><li>在列出的轨道中选择一条，点击即提取并自动开启字幕。</li></ol><blockquote><p>播放时任意跳转到视频位置，提取会<strong>优先处理播放点附近</strong>的轨道段，快速补齐，不会因跳转而长时间缺失字幕。</p></blockquote><h2 id="观众同步" tabindex="-1">观众同步 <a class="header-anchor" href="#观众同步" aria-label="Permalink to &quot;观众同步&quot;">​</a></h2><p>房间内<strong>字幕由房主统一控制</strong>。房主加载或切换字幕轨道后，所有观众会自动同步相同配置，无需单独设置。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="内封字幕列不出轨道" tabindex="-1">内封字幕列不出轨道？ <a class="header-anchor" href="#内封字幕列不出轨道" aria-label="Permalink to &quot;内封字幕列不出轨道？&quot;">​</a></h3><p>确认视频确为 MKV 容器且包含<strong>文本型</strong>字幕轨（SRT / ASS 等）；位图字幕轨（PGS / VOBSUB）无法在浏览器提取。若为直链且源服务器未开放 CORS Range 访问，可能提取失败——请改走服务器中转。</p><h3 id="样式丢失" tabindex="-1">样式丢失？ <a class="header-anchor" href="#样式丢失" aria-label="Permalink to &quot;样式丢失？&quot;">​</a></h3><p>ASS / SSA 内封字幕会保留样式；若源本身是纯文本字幕（如 SRT）则没有样式信息。</p>',30)])])}const p=a(d,[["render",n]]);export{u as __pageData,p as default};
